import {BATCH_CASES,BATCH_INGREDIENTS,BATCH_MODEL,BATCH_TEACHING,BATCH_GLOSSARY} from './whole-batches-content.mjs';
import * as core from './whole-batches-core.mjs';
import {recipeJugArt,recipeIngredientMark,recipeIntervalStrip} from './measuring-recipes-art.mjs';
import {batchCardArt,batchLoafArt,batchGatheringArt} from './whole-batches-art.mjs';
import {hearButton} from './play-media.mjs';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const pages=[['plan','Plan'],['measure','Measure'],['message','Message'],['keep','Keep']];
const ingredients=BATCH_INGREDIENTS;
const name=id=>ingredients.find(i=>i.id===id)?.name||'empty jug';
const btn=(attrs,label,{disabled=false,on=null,primary=false}={})=>`<button type="button" class="${primary?'primary':'secondary'}${on?' selected':''}" ${attrs}${disabled?' disabled':''}${on===null?'':` aria-pressed="${on}"`}>${label}</button>`;
const cards=(n,example=false)=>Array.from({length:n},(_,i)=>batchCardArt(i+1,{example})).join('');
const heading=()=>'<header class="wb-heading"><a class="back" href="#cafe">← Back to my café order</a><h1>Whole batches for a gathering</h1><p>One complete recipe. A tray we can plan, change and offer.</p></header>';
function chooser(r){return `<h2 id="wb-title" tabindex="-1">Which gathering shall we plan for?</h2><p>Choose a pictured request. Each has its own draft to return to.</p><div class="wb-case-grid">${BATCH_CASES.map(c=>btn(`data-wb-case="${c.id}"`,`<strong>${esc(c.title)}</strong><span>${esc(c.purpose)}</span><small>${c.guests} guests${r.cases[c.id]?' · resume your familiar draft':''}</small>`)).join('')}</div>`;}
function strip(v){return `<section class="wb-strip" aria-label="Request and one complete base batch"><div><strong>${esc(v.case.title)} · ${v.case.guests} guests</strong><p>Your plan: ${v.work.copies} complete ${v.work.copies===1?'copy':'copies'} · ${v.work.copies*2} guest places</p></div><div><strong>One complete base batch → 2 guests</strong><p class="wb-base-lines"><span>${recipeIngredientMark('cloud-water')} cloud-water: <b>100 mL</b></span><span>${recipeIngredientMark('star-water')} star-water: <b>150 mL</b></span></p><small>Two separate named portions; the unequal jars are not halves.</small></div></section>`;}
function sums(n){return `<div class="wb-sums">${ingredients.map(i=>`<p><strong>${esc(i.name)}:</strong> ${n?Array(n).fill(`${BATCH_MODEL.base[i.id]} mL`).join(' + '):'no portions planned'}${n?` = ${n*BATCH_MODEL.base[i.id]} mL`:''}</p>`).join('')}${n?`<p><strong>Guests:</strong> ${Array(n).fill('2').join(' + ')} = ${n*2} guests</p><details><summary>Another way to say the same amounts</summary><p>${n} ${n===1?'copy':'copies'} × 100 mL cloud-water = ${n*100} mL cloud-water.<br>${n} ${n===1?'copy':'copies'} × 150 mL star-water = ${n*150} mL star-water.</p></details>`:''}</div>`;}
function feedback(v,kind){const check=v.latestChecks?.[kind];if(!v.work.feedback?.[kind]&&!check)return `<div id="wb-feedback-${kind}" class="wb-feedback" role="status" tabindex="-1" hidden></div>`;const current=v.currentFeedback?.[kind];const assessment=check?.outcome||check?.assessment||check?.result;return `<div id="wb-feedback-${kind}" class="wb-feedback" role="status" tabindex="-1"><strong>${!current?'From your earlier tray · ':''}Let’s look together</strong><p>${esc(typeof current==='string'?current:feedbackText(kind,assessment||v.assessment?.[kind]))}</p><p class="tiny">You can change your plan and try again.</p></div>`;}
function feedbackText(kind,a){
 if(!a)return 'This is the picture we looked at together.';
 if(kind==='plan')return a.matches?`The ${a.copies} complete copies make ${a.guests} guest places and fit the request.`:`${a.copies} copies make ${a.guests} guest places. The request is for ${a.targetGuests}; compare two places on every card.`;
 if(kind==='reading')return `Your number ${a.readNumber}: ${a.numberRead?'matches':'differs from'} the actual ${a.actualAmount} mL in the jug. Unit: ${a.unitNamed?'mL matches liquid volume':'check the liquid-volume unit'}. The recipe target is a separate question.`;
 if(kind==='message')return Object.entries(a.fields).map(([k,ok])=>`${({destination:'Destination',guests:'Guest count',cloud:'Cloud-water amount',cloudUnit:'Cloud-water unit',star:'Star-water amount',starUnit:'Star-water unit'})[k]}: ${ok?'matches':'needs a change'}.`).join(' ');
 if(kind==='reference')return `Cloud-water: ${a.cloud.amount} mL ${a.cloud.matches?'matches':'differs from'} 100 mL. Star-water: ${a.star.amount} mL ${a.star.matches?'matches':'differs from'} 150 mL. Each is for one two-guest base card, not one guest. Familiar supplied practice.`;
 if(kind==='contrast')return `Cloud-water: 200 + ${a.cloud.extra} = ${a.cloud.amount} mL; ${a.cloud.matches?'matches':'differs from'} three complete copies (300 mL). Star-water: 300 + ${a.star.extra} = ${a.star.amount} mL; ${a.star.matches?'matches':'differs from'} three complete copies (450 mL).`;
 return `${Object.entries(a.ingredients).map(([id,x])=>`${name(id)}: ${x.amount} mL ${x.status==='matches'?'matches':x.status==='below'?'is below':'is above'} ${x.target} mL.`).join(' ')} Plan ${a.planFit?'fits':'needs a change'}; jug ${a.jugEmpty?'is empty':'still holds liquid'}; message ${a.messageFit?'matches':'needs a change'}. ${a.ready?'This tray is ready to offer.':'All parts stay revisable.'}`;
}
function plan(v){return {model:`<h3>Complete copies of the base card</h3><div class="wb-copy-stack">${v.work.copies?cards(v.work.copies):'<p class="wb-empty">An open plan. Add a complete card to begin.</p>'}</div>${sums(v.work.copies)}`,task:`<h2 id="wb-title" tabindex="-1">How many complete copies fit?</h2><p>Each card brings two guest places and both portions. Add or remove a whole card.</p><div class="wb-controls">${btn('data-wb-copies="-1"','− Remove one card',{disabled:v.work.copies===0})}${btn('data-wb-copies="1"','+ Add one complete card',{disabled:v.work.copies===3,primary:true})}</div><p>${v.work.copies===0?'Zero cards is an unfinished plan.':`${v.work.copies} complete ${v.work.copies===1?'copy makes':'copies make'} ${v.work.copies*2} guest places. The request is for ${v.case.guests}.`}</p>${btn('data-wb-check="plan"','Check my plan',{primary:true})}${feedback(v,'plan')}<p>${btn('data-wb-page="measure"','Go to the measuring jug')}</p>`};}
function reading(v){return `<form data-wb-form="reading" novalidate><h3>What does the jug show now?</h3><p class="tiny">Read the actual jug, even when it differs from the target.</p><div class="wb-fields"><label>My number<input id="wb-reading" type="text" inputmode="decimal" maxlength="24" autocomplete="off" value="${esc(v.work.reading.text)}"></label><label>My unit<select id="wb-unit">${options([['','Choose unit'],['mL','mL · millilitres'],['g','g · grams'],['items','items']],v.work.reading.unit)}</select></label></div><button type="submit" class="secondary">Check this reading</button></form>${feedback(v,'reading')}`;}
const options=(items,value)=>items.map(([id,label])=>`<option value="${esc(id)}"${String(value??'')===String(id)?' selected':''}>${esc(label)}</option>`).join('');
function jars(v,interactive=false){return `<div class="wb-jars">${ingredients.map(i=>`<section class="wb-jar"><h3>${recipeIngredientMark(i.id)} ${esc(i.name)}</h3>${recipeJugArt(v.model.portions[i.id],i.id,{jar:true,label:`${i.name} preparation jar`})}<p><strong>${v.model.portions[i.id]} mL</strong> in this jar<br><small>Request: ${v.case.targets[i.id]} mL</small></p>${interactive?`${btn(`data-wb-return-portion="${i.id}"`,'Return 50 mL to jug',{disabled:!v.actions?.returnPortions?.[i.id]?.enabled})}${btn(`data-wb-clear-portion="${i.id}"`,'Return jar to source',{disabled:v.model.portions[i.id]===0})}`:''}</section>`).join('')}</div>`;}
function measure(v){const j=v.model.jug,id=v.work.selectedIngredient,a=v.actions;return {model:`<h3>Actual measuring jug</h3><div class="wb-jug-row">${recipeJugArt(j.amount,j.ingredient)}<div><strong>${esc(name(j.ingredient||id))}${j.amount===0?' · empty':''}</strong><p>Selected portion target: <b>${v.case.targets[id]} mL</b></p><p class="tiny">The current jug reading and the requested jar amount are different questions.</p></div></div>${jars(v,true)}`,task:`<h2 id="wb-title" tabindex="-1">Prepare one named portion</h2><div class="wb-controls" role="group" aria-label="Ingredient source">${ingredients.map(i=>btn(`data-wb-ingredient="${i.id}"`,`${recipeIngredientMark(i.id)} ${esc(i.name)}`,{on:id===i.id,disabled:j.amount>0&&j.ingredient!==i.id})).join('')}</div><div class="wb-controls">${btn('data-wb-fill','Add 50 mL',{primary:true,disabled:!a?.fill?.enabled})}${btn('data-wb-return-jug="one"','Return 50 mL',{disabled:j.amount===0})}${btn('data-wb-return-jug="all"','Return jug to source',{disabled:j.amount===0})}${btn('data-wb-pour',`Pour into ${esc(name(j.ingredient||id))} jar`,{primary:true,disabled:!a?.pour?.enabled})}</div>${a?.fill?.reason&&!a.fill.enabled?`<p class="tiny">${esc(a.fill.reason)}</p>`:''}${a?.pour?.reason&&!a.pour.enabled?`<p class="tiny">${esc(a.pour.reason)}</p>`:''}${reading(v)}<details><summary>Separate pretend sources</summary>${ingredients.map(i=>`<p>${esc(i.name)}: ${v.sources[i.id]} mL remaining.</p>`).join('')}<p class="tiny">Returning restores the same ingredient. Each source began with 1000 model mL.</p></details>`};}
function message(v){const m=v.work.message;const field=(key,label,items)=>`<label${key==='destination'?' class="wb-wide"':''}>${label}<select data-wb-message="${key}">${options([['','Choose…'],...items],m[key])}</select></label>`;return {model:`<h3>The pictured request</h3><p><strong>${esc(v.case.title)}</strong></p><p>${v.case.guests} guest places need ${v.case.copies} complete base copies.</p><p>${recipeIngredientMark('cloud-water')} ${v.case.targets['cloud-water']} mL cloud-water</p><p>${recipeIngredientMark('star-water')} ${v.case.targets['star-water']} mL star-water</p>${jars(v)}`,task:`<h2 id="wb-title" tabindex="-1">What message will travel with the tray?</h2><p>Use these supplied phrases. Keep each amount beside its ingredient and unit.</p><form data-wb-form="message"><div class="wb-fields">${field('destination','Please take this tray to',BATCH_CASES.map(c=>[c.id,c.title]))}${field('guests','For this many guests',[2,4,6].map(n=>[n,`${n} guests`]))}${field('cloud','Cloud-water amount',[100,150,200,250,300,350,400,450,500].map(n=>[n,n]))}${field('cloudUnit','Cloud-water unit',[['mL','mL · millilitres'],['g','g · grams'],['items','items']])}${field('star','Star-water amount',[100,150,200,250,300,350,400,450,500].map(n=>[n,n]))}${field('starUnit','Star-water unit',[['mL','mL · millilitres'],['g','g · grams'],['items','items']])}</div><button type="submit" class="primary">Check this message</button></form>${feedback(v,'message')}<p class="tiny">Keep the pictured request beside you while you make your message.</p>`};}
function snapshot(s,label,earlier){if(!s)return '';return `<section class="wb-snapshot"><h3>${label}${earlier?' · earlier work':''}</h3><p>${s.input?.copies??'Kept'} complete copies · ${s.source?.guests??''} requested guests.</p>${ingredients.map(i=>`<p>${recipeIngredientMark(i.id)} ${esc(i.name)}: ${esc(s.input?.model?.portions?.[i.id]??'')} mL</p>`).join('')}<details><summary>See the kept message and details</summary><pre class="wb-note-pre">${esc(JSON.stringify(s,null,2))}</pre></details><p class="tiny">Later edits leave this snapshot as it was.</p></section>`;}
function keep(v){const w=v.work,a=v.assessment;const planOK=w.copies===v.case.copies,portionsOK=ingredients.every(i=>v.model.portions[i.id]===v.case.targets[i.id]),jugOK=v.model.jug.amount===0;const messageOK=!!(a?.message?.matches||a?.message?.correct||a?.message?.fit);return {model:`<h3>Two separate preparation jars</h3>${jars(v)}<p>Separate measuring jug: ${v.model.jug.amount} mL${v.model.jug.ingredient?` ${esc(name(v.model.jug.ingredient))}`:''}.</p>`,task:`<h2 id="wb-title" tabindex="-1">Keep this tray, or offer it?</h2><ul class="wb-summary"><li><strong>Plan</strong>${planOK?'The complete copies fit.':`${w.copies} copies planned; the request needs ${v.case.copies}.`}</li><li><strong>Portions</strong>${portionsOK?'Both named jars match.':'One or both jars need a change.'}</li><li><strong>Jug readiness</strong>${jugOK?'The measuring jug is empty.':'Return or pour the extra jug liquid.'}</li><li><strong>Message</strong>${messageOK?'The literal message matches.':'Compare destination, guests, both amounts and mL.'}</li></ul><div class="wb-controls">${btn('data-wb-check="tray"','Check this whole tray')}${btn('data-wb-keep',w.kept?'Replace kept draft':'Keep this draft',{primary:true})}${btn('data-wb-offer','Offer this tray',{disabled:!a?.tray?.ready||!!(w.offered&&!v.offeredEarlier),primary:true})}</div>${feedback(v,'tray')}<p>Unfinished work can be kept. Offering is a separate choice.</p>${snapshot(w.kept,'Your kept tray',v.keptEarlier)}${w.offered?`${batchGatheringArt(w.offered.source?.guests||v.case.guests)}<h3>A tray joins the gathering</h3><p>${esc(BATCH_TEACHING.ending)}</p>${snapshot(w.offered,'Your offered tray',v.offeredEarlier)}`:''}`};}
function help(v){const w=v.work,topic=w.helpTopic;let content='';if(topic==='whole')content=`${batchLoafArt()}<p>${esc(BATCH_TEACHING.whole)}</p><a href="#cafe/sharing">Visit the Sharing Counter</a>`;else if(topic==='base')content=`${batchCardArt(1,{example:true})}<p>${esc(BATCH_TEACHING.base)}</p>`;else if(topic==='copies')content=`<p>${esc(BATCH_TEACHING.copies)}</p><p>One card makes two guest places. Two complete cards make 2 + 2 = 4 guest places; a third adds two more.</p>`;else if(topic==='example')content=`<p class="wb-support-notice">A separate worked example · supplied support</p>${worked(v)}`;else if(topic==='contrast')content=contrast(v);else if(topic==='reference')content=reference(v);else if(topic==='scale')content=`${recipeIntervalStrip()}<p>${esc(BATCH_TEACHING.scale)}</p><p>mL names volume. 500 mL is the maximum capacity; the amount now can be smaller.</p>`;else if(topic==='message')content=`<p>${esc(BATCH_TEACHING.message)}</p>`;else if(topic==='glossary')content=`<dl>${Object.entries(BATCH_GLOSSARY).map(([k,text])=>`<dt><strong>${esc(k)}</strong></dt><dd>${esc(text)}</dd>`).join('')}</dl>`;return `<aside class="wb-ideas"><h2>Ideas to try together</h2><p class="tiny">Try a picture, explanation or example. Your tray stays as you left it.</p><div class="wb-idea-nav">${[['whole','Name the whole'],['base','Read one card'],['copies','Repeating the whole'],['example','A different worked example'],['contrast','A tempting shortcut'],['reference','Find one base card'],['scale','Read the scale'],['message','Message help'],['glossary','Word pictures']].map(([id,label])=>btn(`data-wb-help="${id}"`,label,{on:topic===id})).join('')}</div>${topic?`<section class="wb-help" tabindex="-1" id="wb-help"><p class="wb-support-notice">Another way to look · your tray stays as you left it</p>${content}${btn('data-wb-help=""','Close ideas')}</section>`:''}<div class="wb-controls">${btn('data-wb-together','We’re working together',{on:!!w.support.together})}${btn('data-wb-ready','Make a ready example together')}<span data-wb-audio>${hearButton(`${v.case.purpose} One complete base batch serves two guests. It has 100 millilitres of cloud-water and 150 millilitres of star-water in separate jars. ${pages.find(([id])=>id===v.page)?.[1]||''}.`,'Hear the request and base card')}</span></div><p class="tiny">The ready example fills in this request’s plan, jars and message with your companion. It leaves kept trays alone. You still choose whether to offer it.</p></aside>`;}
function worked(v){const e=v.example||{},n=e.copies|| (v.case.copies===2?1:2);return `<div class="wb-copy-stack">${cards(n,true)}</div>${sums(n)}<p>These ${n} complete copies are a different guest request from your real tray.</p><p>${['Start with the complete base: both named portions and two guests.','Copy the entire card; do not change just one named portion.','Add the same ingredient amounts: each sum keeps its own mL label.','Compare the two guest places on each card with the repeated guest sum.'][e.step??0]}</p><div class="wb-controls">${btn('data-wb-example="-1"','Previous example step',{disabled:!e.step})}${btn('data-wb-example="1"','Next example step',{disabled:e.step===3})}</div>`;}
function contrast(v){const c=v.work.contrast;return `<h3>What does one more complete batch add?</h3><p>${esc(BATCH_TEACHING.contrast)}</p><p>Separate practice starts at two copies: 200 mL cloud-water and 300 mL star-water.</p>${ingredients.map(i=>{const key=i.id==='cloud-water'?'cloud':'star';return `<p><strong>${esc(i.name)} extra: ${c[key]} mL</strong> → practice jar ${(key==='cloud'?200:300)+c[key]} mL</p><div class="wb-controls">${btn(`data-wb-contrast="${i.id}" data-wb-delta="-50"`,'− 50 mL',{disabled:c[key]===0})}${btn(`data-wb-contrast="${i.id}" data-wb-delta="50"`,'+ 50 mL',{disabled:c[key]>=200})}</div>`;}).join('')}${btn('data-wb-check="contrast"','Check these extra portions')}${feedback(v,'contrast')}<p class="tiny">Cloud-water alone cannot distinguish adding 100 to both from adding a whole batch. Look at star-water.</p>`;}
function reference(v){return `<h3>Find the familiar two-guest base card</h3><p>${esc(BATCH_TEACHING.reference)}</p><div class="wb-copy-stack">${cards(2,true)}</div><p>Two equal complete groups: 4 guests, 200 mL cloud-water, 300 mL star-water.</p><form data-wb-form="reference" novalidate><div class="wb-fields">${[['cloud','Cloud-water'],['star','Star-water']].map(([key,label])=>`<label>${label} on one 2-guest base card (mL)<input id="wb-reference-${key}" data-wb-reference="${key}" type="text" inputmode="decimal" autocomplete="off" maxlength="24" value="${esc(v.work.reference[key])}"></label>`).join('')}</div><button type="submit" class="secondary">Check these base-card amounts</button></form>${feedback(v,'reference')}${btn('data-wb-reference-reveal','Show the two matching shares')}<div${v.work.support.referenceReveal?'':' hidden'}><p class="wb-support-notice">Worked answer · familiar supplied help</p><p>200 mL cloud-water shared into two equal card groups gives 100 mL on each. 300 mL star-water gives 150 mL on each. Each group is for two guests, not one guest.</p></div>`;}
export function wholeBatchesEntry(){return '<aside class="wb-entry"><div><h2>A whole recipe for a gathering</h2><p>Repeat a complete two-guest batch, prepare separate portions and send a clear message.</p></div><a class="secondary" href="#cafe/batches">Plan a gathering tray</a></aside>';}
export function wholeBatchesPage(state){const r=core.batchState(state);if(!r)return '<section class="wb-workspace" data-wb-root><h1 id="wb-title" tabindex="-1">An earlier gathering record is kept</h1><p>This format cannot be opened here. Its exact raw record stays available in your notes download.</p><button type="button" class="secondary" data-wb-recover>Keep the earlier record and start fresh</button><p><a href="#cafe">Return to the café</a></p></section>';if(r.page==='choose'||!r.currentCase)return `<div class="wb-workspace" data-wb-root>${heading()}${chooser(r)}</div>`;const v={...core.batchView(state),page:r.page},content=({plan,measure,message,keep}[r.page]||plan)(v);return `<div class="wb-workspace wb-page-${r.page}" data-wb-root>${heading()}${strip(v)}<nav class="wb-pages" aria-label="Open gathering task pages">${pages.map(([id,label])=>btn(`data-wb-page="${id}"`,label,{on:r.page===id})).join('')}</nav><p class="tiny">${esc(BATCH_MODEL.notice)} You can go back and change anything.</p><div class="wb-layout"><section class="wb-model" aria-label="Relevant pictured source and model">${content.model}</section><section class="wb-turn">${content.task}</section></div><p id="wb-action-status" class="wb-status" role="status" tabindex="-1">${esc(v.work.inputError?'Use a whole number from 0 to 500. Blank or malformed entries remain drafts.':'')}</p>${help(v)}<details><summary>About this picture machine</summary><p>${esc(BATCH_MODEL.details)} Each transfer is exactly 50 model mL. This picture does not model real pouring uncertainty or physical-tool skill.</p></details><div class="wb-footer">${btn('data-wb-page="choose"','Choose another gathering')}<a href="#cafe/sharing">Sharing Counter</a><a href="#cafe/recipes">Measuring Kitchen</a><a href="#notes">Grown-up notes</a></div></div>`;}
export function wholeBatchesNotes(state){if(!Object.hasOwn(state,'wholeBatches'))return '';return `<details class="panel" data-wb-notes><summary>Whole batches: plans, separate portions and messages</summary><p>Familiar supplied picture practice. Checks retain the exact model, literal response and support at that time. Keeping and offering preserve separate snapshots; no independent reading, writing or physical measuring competence, café serve or act completion is inferred.</p><pre class="wb-note-pre">${esc(JSON.stringify(state.wholeBatches,null,2))}</pre></details>`;}

export function bindWholeBatches(state,ctx){
 if(!document.querySelector('[data-wb-root]'))return;
 const focus=selector=>{const el=document.querySelector(selector);ctx.focus?.(el&&!el.disabled?selector:'#wb-title');};
 const refresh=(target='#wb-title')=>{ctx.save();ctx.render();focus(target);};
 const status=text=>{const el=document.querySelector('#wb-action-status');if(el){el.textContent=text;focus('#wb-action-status');}};
 const act=(fn,target='#wb-title')=>{const result=fn();if(result!==false&&result!==null)refresh(result?.valid===false?'#wb-action-status':target);else status('That move is not available. Your draft is still here.');};
 const all=(selector,fn)=>document.querySelectorAll(selector).forEach(b=>b.addEventListener('click',()=>fn(b)));
 all('[data-wb-case]',b=>act(()=>core.chooseBatchCase(state,b.dataset.wbCase)));
 all('[data-wb-page]',b=>act(()=>core.setBatchPage(state,b.dataset.wbPage)));
 all('[data-wb-recover]',()=>act(()=>core.recoverBatches(state)));
 all('[data-wb-copies]',b=>act(()=>core.setBatchCopies(state,core.batchView(state).work.copies+Number(b.dataset.wbCopies)),`[data-wb-copies="${b.dataset.wbCopies}"]`));
 all('[data-wb-ingredient]',b=>{if(core.batchView(state).work.selectedIngredient!==b.dataset.wbIngredient)act(()=>core.chooseBatchIngredient(state,b.dataset.wbIngredient),`[data-wb-ingredient="${b.dataset.wbIngredient}"]`);});
 all('[data-wb-fill]',()=>act(()=>core.fillBatchJug(state),'[data-wb-fill]'));
 all('[data-wb-return-jug]',b=>act(()=>core.returnBatchJug(state,b.dataset.wbReturnJug==='all'),`[data-wb-return-jug="${b.dataset.wbReturnJug}"]`));
 all('[data-wb-pour]',()=>act(()=>core.pourBatchJug(state),'[data-wb-pour]'));
 all('[data-wb-return-portion]',b=>act(()=>core.returnBatchPortion(state,b.dataset.wbReturnPortion),`[data-wb-return-portion="${b.dataset.wbReturnPortion}"]`));
 all('[data-wb-clear-portion]',b=>act(()=>core.returnBatchPortion(state,b.dataset.wbClearPortion,true),`[data-wb-clear-portion="${b.dataset.wbClearPortion}"]`));
 const check=kind=>act(()=>core[{plan:'checkBatchPlan',reading:'checkBatchReading',message:'checkBatchMessage',tray:'checkBatchTray',reference:'checkBatchReference',contrast:'checkBatchContrast'}[kind]](state),`#wb-feedback-${kind}`);
 all('[data-wb-check]',b=>check(b.dataset.wbCheck));
 document.querySelectorAll('[data-wb-form]').forEach(form=>form.addEventListener('submit',e=>{e.preventDefault();check(form.dataset.wbForm);}));
 all('[data-wb-keep]',()=>act(()=>core.keepBatch(state),'#wb-title'));
 all('[data-wb-offer]',()=>act(()=>core.offerBatch(state),'#wb-title'));
 all('[data-wb-ready]',()=>{act(()=>core.makeBatchTogether(state),'#wb-action-status');status('We prepared this request together. Your earlier kept trays are still there. Choose Keep to review this tray and decide whether to offer it.');});
 all('[data-wb-together]',()=>act(()=>core.useBatchSupport(state,'together'),'[data-wb-together]'));
 all('[data-wb-help]',b=>act(()=>core.setBatchHelp(state,b.dataset.wbHelp||null),b.dataset.wbHelp?'#wb-help':`[data-wb-help="${core.batchView(state).work.helpTopic||'whole'}"]`));
 all('[data-wb-example]',b=>act(()=>core.stepBatchExample(state,Number(b.dataset.wbExample)),`[data-wb-example="${b.dataset.wbExample}"]`));
 all('[data-wb-reference-reveal]',()=>act(()=>core.useBatchSupport(state,'referenceReveal'),'#wb-help'));
 all('[data-wb-contrast]',b=>act(()=>core.adjustBatchContrast(state,b.dataset.wbContrast,Number(b.dataset.wbDelta)),`[data-wb-contrast="${b.dataset.wbContrast}"][data-wb-delta="${b.dataset.wbDelta}"]`));
 document.querySelectorAll('[data-wb-audio] [data-speak]').forEach(b=>b.addEventListener('click',()=>{core.useBatchSupport(state,'audio');ctx.save();}));
 // Draft edits save in place: no render, so typing preserves caret and focus.
 const saved=changed=>{if(!changed)return;ctx.save();document.querySelectorAll('.wb-feedback').forEach(el=>{el.hidden=true;});const el=document.querySelector('#wb-action-status');if(el)el.textContent='Your change is kept. You can check it when you’re ready.';};
 document.querySelector('#wb-reading')?.addEventListener('input',e=>saved(core.setBatchReading(state,e.target.value)));
 document.querySelector('#wb-unit')?.addEventListener('change',e=>saved(core.setBatchUnit(state,e.target.value||null)));
 document.querySelectorAll('[data-wb-reference]').forEach(el=>el.addEventListener('input',e=>saved(core.setBatchReference(state,el.dataset.wbReference,e.target.value))));
 document.querySelectorAll('[data-wb-message]').forEach(el=>el.addEventListener('change',e=>{const field=el.dataset.wbMessage,raw=e.target.value;const value=raw===''?null:['guests','cloud','star'].includes(field)?Number(raw):raw;saved(core.setBatchMessage(state,field,value));}));
}
